// Solar power station showpiece, hand-made. Units: cm, real size. One 2.5 MW block in full detail (16 rows of single-axis
// trackers that turn east → west with the sun), five more blocks around it simplified; the inverter, transformer, the
// pooling substation and its line in front (+Z). The trackers' rows run north–south (Z); the sun rises in the east (+X).
const S = W.store;
S.matte = (c, r = 0.92) => new THREE.MeshStandardMaterial({ color: c, roughness: r, metalness: 0 });
S.lamps = [];
S.lamp = (c = '#ffe2a8', k = 2.4) => { const m = W.glow(c, 0); S.lamps.push({ m, k }); return m; };
S.ROWS = []; for (let i = 0; i < 16; i++) S.ROWS.push(-4875 + i * 650);
S.ROWLEN = 6000; S.AXIS = 260;
S.BLOCKS = [[-11500, 0], [11500, 0], [-11500, -11500], [0, -11500], [11500, -11500]];
W.day({ start: 11, ground: '#9b8a6a', zoom: 0.7 });
const site = W.group();
site.add(W.mesh(W.box(36000, 10, 30000), S.matte('#a8977a', 0.98), { at: [0, -4, -3500] }));
const road = S.matte('#7d7468', 0.95);
for (const [x, z, w, d] of [[0, 5200, 36000, 500], [-5750, -3000, 400, 17000], [5750, -3000, 400, 17000], [0, -5750, 36000, 400], [0, 8000, 500, 6000]]) site.add(W.mesh(W.box(w, 6, d), road, { at: [x, 2, z] }));
site.add(W.text('JARVIS సోలార్ పవర్ స్టేషన్ · 50 MW', { size: 140, at: [0, 300, 11650], color: '#fff8e8', bg: '#c27a1e' }));
for (const x of [-2300, 2300]) site.add(W.mesh(W.cyl(12, 12, 300, 8), W.metal('#8d939a'), { at: [x, 150, 11640] }));
W.add(site, { label: 'సోలార్ ఫారం నేల', ground: true });
const fence = W.group();
const fm = W.metal('#9aa2aa', { rough: 0.5 });
const fx0 = -17800, fx1 = 17800, fz0 = -17800, fz1 = 11400;
for (const [a, b] of [[[fx0, fz0], [fx1, fz0]], [[fx1, fz0], [fx1, fz1]], [[fx0, fz1], [fx1, fz1]], [[fx0, fz0], [fx0, fz1]]]) {
  const L = Math.hypot(b[0] - a[0], b[1] - a[1]), alongX = a[1] === b[1];
  fence.add(W.mesh(W.box(alongX ? L : 6, 180, alongX ? 6 : L), new THREE.MeshStandardMaterial({ color: '#8f989f', metalness: 0.6, roughness: 0.5, transparent: true, opacity: 0.35, depthWrite: false }), { at: [(a[0] + b[0]) / 2, 90, (a[1] + b[1]) / 2] }));
  const n = Math.floor(L / 600);
  for (let i = 0; i <= n; i++) fence.add(W.mesh(W.box(10, 220, 10), fm, { at: [a[0] + (b[0] - a[0]) * i / n, 110, a[1] + (b[1] - a[1]) * i / n] }));
}
W.add(fence, { label: 'కంచె', ground: true });

const S = W.store;
// a panel: 2.3 m × 1.1 m, 72 blue cells in a white frame; two panels side by side across each tracker's tube
const cellTex = W.canvasTex(256, 512);
{
  const g = cellTex.ctx;
  g.fillStyle = '#e8ecef'; g.fillRect(0, 0, 256, 512);
  for (let r = 0; r < 12; r++) for (let c = 0; c < 6; c++) {
    const x = 8 + c * 40.5, y = 8 + r * 41.5;
    const gr = g.createLinearGradient(x, y, x + 38, y + 39); gr.addColorStop(0, '#1d3d7a'); gr.addColorStop(1, '#13295a');
    g.fillStyle = gr; g.fillRect(x, y, 38, 39);
    g.fillStyle = 'rgba(210,220,235,0.55)'; for (const fy of [13, 26]) g.fillRect(x, y + fy, 38, 1.4);
  }
  cellTex.update();
}
S.panelM = new THREE.MeshPhysicalMaterial({ map: cellTex.texture, roughness: 0.38, metalness: 0.05, clearcoat: 0.35, clearcoatRoughness: 0.2, envMapIntensity: 0.45 });
S.dustC = new THREE.Color('#c7a982');
const panels = W.group(), trackers = W.group();
S.rowGroups = [];
const pgRot = new THREE.BoxGeometry(230, 4, 113); // (across the tube: the long side across)
const Mx = new THREE.Matrix4();
for (const x of S.ROWS) {
  const row = W.group({ at: [x, S.AXIS, 0] });
  const n = 52, im = new THREE.InstancedMesh(pgRot, S.panelM, n * 2);
  let k = 0;
  for (let i = 0; i < n; i++) for (const s of [-1, 1]) im.setMatrixAt(k++, Mx.makeTranslation(s * 117, 14, -S.ROWLEN / 2 + 57 + i * (S.ROWLEN - 113) / (n - 1)));
  row.add(im);
  panels.add(row);
  S.rowGroups.push(row);
  trackers.add(W.mesh(W.cyl(7, 7, S.ROWLEN, 10), W.metal('#b9c0c6', { rough: 0.4 }), { at: [x, S.AXIS, 0], rot: [90, 0, 0] }));
  for (let z = -S.ROWLEN / 2 + 300; z <= S.ROWLEN / 2 - 300; z += 700) trackers.add(W.mesh(W.box(14, S.AXIS, 10), W.metal('#9aa2aa'), { at: [x, S.AXIS / 2, z] }));
  trackers.add(W.mesh(W.box(40, 50, 60), W.paint('#3a3f46'), { at: [x, S.AXIS - 40, 50] })); // its drive motor
}
W.add(panels, { label: 'సోలార్ ప్యానెళ్ళు', heat: [30, 62] });
W.add(trackers, { label: 'ట్రాకర్లు', heat: [30, 45] });
// the other blocks, simpler: each row one long strip that turns the same way
const far = W.group();
const stripTex = cellTex.texture.clone(); stripTex.needsUpdate = true; stripTex.wrapS = stripTex.wrapT = THREE.RepeatWrapping; stripTex.repeat.set(2, 26);
S.farM = new THREE.MeshPhysicalMaterial({ map: stripTex, roughness: 0.4, metalness: 0.05, clearcoat: 0.3, envMapIntensity: 0.45 });
const nFar = S.BLOCKS.length * 16;
S.far = new THREE.InstancedMesh(new THREE.BoxGeometry(460, 6, S.ROWLEN), S.farM, nFar);
S.farAt = [];
for (const [bx, bz] of S.BLOCKS) for (const x of S.ROWS) S.farAt.push([bx + x, S.AXIS, bz]);
S.farAt.forEach((p, i) => S.far.setMatrixAt(i, Mx.makeTranslation(p[0], p[1], p[2])));
far.add(S.far);
for (const [bx, bz] of S.BLOCKS) far.add(W.mesh(W.box(500, 260, 240), W.paint('#eef1f3', { metallic: 0.2, rough: 0.5 }), { at: [bx + 5750, 130, bz] }));
W.add(far, { label: 'మిగతా సోలార్ బ్లాకులు', heat: [30, 62] });

const S = W.store;
const cb = W.group();
for (let i = 0; i < 16; i += 2) cb.add(W.mesh(W.box(80, 100, 40), W.paint('#dfe3e6', { metallic: 0.2, rough: 0.5 }), { at: [(S.ROWS[i] + S.ROWS[i + 1]) / 2, 120, 3150] }));
cb.add(W.mesh(W.box(5300, 8, 30), W.rubber('#2a2b2e'), { at: [0, 6, 3300] }));
W.add(cb, { label: 'కంబైనర్ బాక్సులు', heat: [32, 50] });
const inv = W.group();
const white = W.paint('#eef1f3', { metallic: 0.2, rough: 0.5 });
inv.add(W.mesh(W.box(1200, 270, 250), white, { at: [6500, 145, 1200] }));
inv.add(W.mesh(W.box(1220, 20, 270), S.matte('#9aa1a8'), { at: [6500, 10, 1200] }));
const louv = W.canvasTex(128, 64);
{ const g = louv.ctx; g.fillStyle = '#d6dbdf'; g.fillRect(0, 0, 128, 64); for (let y = 4; y < 64; y += 6) { g.fillStyle = '#9aa3ab'; g.fillRect(4, y, 120, 2); } louv.update(); }
for (const x of [6100, 6500, 6900]) inv.add(W.mesh(new THREE.PlaneGeometry(300, 180), new THREE.MeshStandardMaterial({ map: louv.texture, roughness: 0.6 }), { at: [x, 150, 1326] }));
inv.add(W.text('ఇన్వర్టర్ · DC → AC', { size: 34, at: [6500, 255, 1327], color: '#2f5f8a' }));
W.add(inv, { label: 'ఇన్వర్టర్', heat: [32, 58] });
const tr = W.group();
const tank = W.paint('#5f6b5e', { metallic: 0.35, rough: 0.55 });
tr.add(W.mesh(W.box(500, 40, 400), S.matte('#bdb7ab'), { at: [6500, 20, -400] }));
tr.add(W.mesh(W.box(320, 260, 240), tank, { at: [6500, 170, -400] }));
for (let i = 0; i < 8; i++) tr.add(W.mesh(W.box(8, 200, 80), tank, { at: [6360 + i * 40, 160, -560] }));
for (let k = 0; k < 3; k++) tr.add(W.mesh(W.cyl(12, 16, 110, 10), S.matte('#7a4a32', 0.4), { at: [6420 + k * 80, 350, -400] }));
W.add(tr, { label: 'ట్రాన్స్‌ఫార్మర్', heat: [32, 70] });
const ss = W.group();
const gal = W.metal('#aab2ba', { rough: 0.45 });
ss.add(W.mesh(W.box(4000, 10, 2400), S.matte('#8b867d', 0.98), { at: [-3000, 5, 8600] }));
ss.add(W.mesh(W.box(700, 420, 500), tank, { at: [-3800, 240, 8600] }));
for (let i = 0; i < 10; i++) ss.add(W.mesh(W.box(10, 340, 140), tank, { at: [-4100 + i * 64, 230, 8920] }));
for (let k = 0; k < 3; k++) ss.add(W.mesh(W.cyl(18, 26, 220, 10), S.matte('#7a4a32', 0.4), { at: [-3950 + k * 150, 560, 8600] }));
for (const x of [-2600, -1400]) { for (const z of [7700, 9500]) ss.add(W.mesh(W.box(50, 1500, 50), gal, { at: [x, 750, z] })); ss.add(W.mesh(W.box(50, 50, 1850), gal, { at: [x, 1500, 8600] })); }
for (const z of [8200, 8600, 9000]) {
  ss.add(W.mesh(W.cyl(22, 22, 220, 10), S.matte('#9aa1a8', 0.5), { at: [-2000, 330, z] }));
  ss.add(W.mesh(W.box(22, 220, 22), gal, { at: [-2000, 110, z] }));
}
ss.add(W.text('33 kV → 132 kV', { size: 60, at: [-3800, 380, 8852], color: '#eef2f5' }));
W.add(ss, { label: 'సబ్‌స్టేషన్', heat: [30, 66] });
const line = W.group();
for (const [x, z] of [[2600, 11000], [9000, 13800]]) {
  const t = W.group({ at: [x, 0, z] });
  for (const [dx, dz] of [[-1, -1], [-1, 1], [1, -1], [1, 1]]) {
    const A = new THREE.Vector3(dx * 200, 0, dz * 200), B = new THREE.Vector3(dx * 40, 2600, dz * 40);
    const m = new THREE.Mesh(new THREE.CylinderGeometry(10, 10, A.distanceTo(B), 4), gal);
    m.position.copy(A).add(B).multiplyScalar(0.5); m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), B.clone().sub(A).normalize());
    t.add(m);
  }
  t.add(W.mesh(W.box(1300, 36, 36), gal, { at: [0, 2300, 0], rot: [0, 25, 0] }), W.mesh(W.cone(50, 360, 4), gal, { at: [0, 2780, 0] }));
  line.add(t);
}
for (const d of [-500, 0, 500]) line.add(W.mesh(W.tube([[-1400, 1480, 8600 + d], [700, 1900, 9800 + d], [2600 + d * 0.9, 2300, 11000 + d * 0.4], [5800, 1900, 12400 + d * 0.4], [9000 + d * 0.9, 2300, 13800 + d * 0.4]], 6, 24), W.metal('#6c7076')));
W.add(line, { label: 'ట్రాన్స్‌మిషన్ లైన్', heat: [28, 45] });

const S = W.store;
// the control room and the weather mast; then running: the trackers follow the sun (they lie flat at night and in a storm);
// the power follows the sun's height × the power bar (☀️ how clear the sky is) × the heat (hot panels give less);
// 🚩 "dust": a dusty film cuts the power until the cleaning robot runs along the rows
const cr = W.group();
cr.add(W.mesh(W.box(1400, 420, 800), S.matte('#ece6da', 0.8), { at: [-8000, 210, 8400] }));
cr.add(W.mesh(W.box(1440, 40, 840), W.paint('#c27a1e'), { at: [-8000, 440, 8400] }));
cr.add(W.mesh(W.box(1100, 140, 20), S.lamp('#bfe6ff', 1.2), { at: [-8000, 260, 8810] }));
S.lamps[S.lamps.length - 1].always = 0.6;
const mast = W.group({ at: [-6600, 0, 7600] });
mast.add(W.mesh(W.cyl(8, 10, 900, 8), W.metal('#c9cdd2')));
mast.position.y = 0;
mast.children[0].position.y = 450;
mast.add(W.mesh(W.cyl(18, 18, 14, 16), S.matte('#f4f4f2', 0.3), { at: [60, 860, 0] }), W.mesh(W.sphere(9, 12), W.glass({ tint: '#e8f4ff' }), { at: [60, 872, 0] }));
const cups = W.group({ at: [0, 920, 0] });
for (let k = 0; k < 3; k++) cups.add(W.mesh(W.sphere(12, 10), W.metal('#c9cdd2'), { at: [Math.cos(k * 2.094) * 45, 0, Math.sin(k * 2.094) * 45] }), W.mesh(W.box(90, 4, 4), W.metal('#c9cdd2'), { at: [Math.cos(k * 2.094) * 22, 0, Math.sin(k * 2.094) * 22], rot: [0, -k * 120, 0] }));
mast.add(cups);
cr.add(mast);
W.add(cr, { label: 'కంట్రోల్ రూమ్', heat: [24, 26] });
const bot = W.group({ at: [S.ROWS[8], S.AXIS + 40, -2900] });
bot.add(W.mesh(W.box(500, 40, 120), W.paint('#e0b324', { metallic: 0.2, rough: 0.45 })));
bot.add(W.mesh(W.cyl(18, 18, 480, 16), W.rubber('#3b3f45'), { at: [0, -10, 60], rot: [0, 0, 90] }));
W.add(bot, { label: 'క్లీనింగ్ రోబో' });
W.throttle({ label: 'ఎండ', rise: 0.5, fall: 0.5, start: 1 });
const invV = W.sound({ kind: 'hum', label: 'ఇన్వర్టర్', gain: 0.45, f0: 100 });
const fanV = W.sound({ kind: 'fans', label: 'ట్రాన్స్‌ఫార్మర్', gain: 0.3 });
const hum = W.sound({ kind: 'hum', label: 'సబ్‌స్టేషన్', gain: 0.25, f0: 100 });
let tilt = 0, hudT = 0, mw = 0, dust = 0, clean = 1, wasDust = false, cupA = 0;
const Mx = new THREE.Matrix4(), Q = new THREE.Quaternion(), Z = new THREE.Vector3(0, 0, 1), P = new THREE.Vector3(), Sc = new THREE.Vector3(1, 1, 1);
const base = S.panelM.color.clone();
W.onTick((t, dt) => {
  const s = Math.min(1, W.env.spool), h = W.env.hour, a = ((h - 6) / 12) * Math.PI, up = Math.sin(a);
  const storm = W.env.over;
  let want = up > 0.02 ? Math.atan2(-Math.cos(a), up) : 0;
  want = storm ? 0 : Math.max(-0.96, Math.min(0.96, want));
  tilt += (want - tilt) * Math.min(1, dt * 0.8);
  const stuck = W.faultOf('ట్రాకర్లు') === 'stop';
  S.rowGroups.forEach((r, i) => { r.rotation.z = stuck && i === 5 ? 0 : tilt; });
  Q.setFromAxisAngle(Z, tilt);
  S.farAt.forEach((p, i) => S.far.setMatrixAt(i, Mx.compose(P.set(p[0], p[1], p[2]), Q, Sc)));
  S.far.instanceMatrix.needsUpdate = true;
  const d = W.env.flag('dust');
  if (d) { dust = Math.min(1, dust + dt * 0.8); clean = 0; } else if (wasDust || clean < 1) { clean = Math.min(1, clean + dt / 7); dust = Math.max(0, dust - dt / 6); }
  wasDust = d;
  bot.position.z = clean < 1 ? -2900 + 5800 * Math.sin(clean * Math.PI) : -2900;
  S.panelM.color.copy(base).lerp(S.dustC, dust * 0.65);
  S.farM.color.copy(base).lerp(S.dustC, dust * 0.65);
  cupA += dt * (1 + 3 * s); cups.rotation.y = cupA;
  for (const l of S.lamps) l.m.emissiveIntensity = l.k * Math.max(l.always || 0, W.env.dark);
  const T = W.env.ambient + 25 * W.env.sun;
  const kTemp = 1 - 0.004 * Math.max(0, T - 25), kTrack = stuck ? 0.97 : 1;
  const pv = Math.pow(Math.max(0, Math.min(1, up / 0.45)), 0.9); // (a tracker keeps facing the sun: low sun, still a fair share)
  const out = 50 * pv * s * kTemp * (1 - 0.22 * dust) * kTrack;
  mw += (Math.min(50, out) - mw) * Math.min(1, dt * 2);
  const lev = mw / 50;
  fanV.set(lev); hum.set(lev); invV.set(lev);
  if (t - hudT > 0.25) {
    hudT = t;
    W.hud({ 'విద్యుత్': mw.toFixed(1) + ' MW', 'ఎండ బలం': Math.round(1000 * Math.max(0, up) * s) + ' W/m²', 'ప్యానెల్ వేడి': Math.round(T) + '°C', 'ట్రాకర్ వాలు': Math.round(-tilt * 57.3) + '°',
      'దుమ్ము': d ? (dust > 0.5 ? 'ఉంది (−22%)' : 'పడుతోంది') : clean < 1 ? 'శుభ్రం చేస్తోంది' : 'శుభ్రం' });
    W.report({ power: s, mw, sun: W.env.sun, temp: T });
  }
});
for (let i = 0; i < 16; i += 3) W.stream([[S.ROWS[i], 3500, -2000], [S.ROWS[i], 1200, -1000], [S.ROWS[i], S.AXIS + 30, 0]], { kind: 'sun', count: 12, size: 90, speed: 0.6, when: (e) => e.sun > 0.05 });
W.stream([[S.ROWS[1], 300, -2500], [S.ROWS[1], 300, 3150], [0, 120, 3300], [5800, 120, 3300], [6500, 200, 1200]], { kind: 'power', count: 30, size: 70, speed: 0.8, when: (e) => e.sun > 0.05 });
W.stream([[6500, 200, 1200], [6500, 200, -400], [6000, 100, 4500], [0, 100, 5200], [-3800, 300, 8600], [-2000, 1480, 8600], [2600, 2300, 11000], [9000, 2300, 13800]], { kind: 'power', count: 40, size: 110, speed: 1, when: (e) => e.sun > 0.05 });
W.walk({ eye: 165, speed: 300, area: [-17600, -17600, 17600, 11200],
  solid: S.ROWS.map((x) => [x - 245, -3000, x + 245, 3000]).concat([[5900, 1075, 7100, 1325], [6250, -600, 6750, -200], [-8700, 8000, -7300, 8800], [-4150, 8350, -3450, 8850]]),
  spots: [
    { name: 'ప్యానెళ్ళ వరుసల మధ్య', at: [(S.ROWS[7] + S.ROWS[8]) / 2, 0, -3600], look: [(S.ROWS[7] + S.ROWS[8]) / 2, 120, 2000] },
    { name: 'ఇన్వర్టర్ దగ్గర', at: [5000, 0, 2600], look: [6500, 150, 1000] },
    { name: 'సబ్‌స్టేషన్', at: [-600, 0, 10800], look: [-3000, 500, 8600] },
    { name: 'ఫారం అంచున', at: [4800, 0, 4400], look: [-2500, 200, -4000] },
  ] });

