// Inside a solar panel, its layers pulled apart (a corner, 60 cm across): glass on top, a clear glue film (EVA), the blue
// silicon cells with thin silver lines, another film, the white back sheet, the aluminium frame. Sunlight (yellow) goes in;
// each cell pushes electrons (gold) along its silver lines to the busbars and out to the junction box.
const L = 60;
const gl = W.group();
gl.add(W.mesh(W.box(L, 0.8, L), W.glass({ tint: '#eaf6ff' }), { at: [0, 40, 0] }));
W.add(gl, { label: 'గ్లాస్' });
const eva = new THREE.MeshStandardMaterial({ color: '#f4f7f9', transparent: true, opacity: 0.35, roughness: 0.4, depthWrite: false });
const e1 = W.group(); e1.add(W.mesh(W.box(L, 0.5, L), eva, { at: [0, 30, 0] })); W.add(e1, { label: 'EVA పొర' });
const cells = W.group();
const cellM = W.paint('#1b3a78', { metallic: 0.2, rough: 0.35 }), silver = W.metal('#d8dde2', { rough: 0.25 });
for (const cx of [-15, 15]) for (const cz of [-15, 15]) {
  cells.add(W.mesh(W.box(15.6, 0.4, 15.6), cellM, { at: [cx, 20, cz] }));
  for (let i = -7; i <= 7; i++) cells.add(W.mesh(W.box(15.4, 0.12, 0.12), silver, { at: [cx, 20.25, cz + i]}));
  for (const bz of [-5, 0, 5]) cells.add(W.mesh(W.box(0.5, 0.18, 15.6), silver, { at: [cx + bz, 20.3, cz] }));
}
W.add(cells, { label: 'సిలికాన్ సెల్స్' });
const e2 = W.group(); e2.add(W.mesh(W.box(L, 0.5, L), eva, { at: [0, 10, 0] })); W.add(e2, { label: 'EVA పొర కింది' });
const back = W.group(); back.add(W.mesh(W.box(L, 0.6, L), W.plastic('#f2f2ee'), { at: [0, 0, 0] })); W.add(back, { label: 'బ్యాక్‌షీట్' });
const fr = W.group();
for (const [x, z, w, d] of [[0, -L / 2 - 1, L + 4, 2], [0, L / 2 + 1, L + 4, 2], [-L / 2 - 1, 0, 2, L], [L / 2 + 1, 0, 2, L]]) fr.add(W.mesh(W.box(w, 4, d), W.metal('aluminium'), { at: [x, -8, z] }));
